INSERT INTO `juego` (`id`, `id_desarrollador`, `nombre`, `descripcion`, `fecha_lanzamiento`, `genero1`, `genero2`, `tipo`, `imagen`) VALUES
(1, 1, 'Monster hunter', 'Juego muy divertido', '2025-02-28', 'Aventura', 'Accion', 'single/multiplayer', );
INSERT INTO `juego` (`id`, `id_desarrollador`, `nombre`, `descripcion`, `fecha_lanzamiento`, `genero1`, `genero2`, `tipo`, `imagen`) VALUES
(3, 11, 'Pokémon Edición Platino ', 'El juego presenta como Pokémon principal a Giratina, e introduce su Forma Origen (オリジンフォルム Orijin Forumu), vista en la película Giratina y el Guardián de los Cielos. Su forma antigua será conocida como Forma Modificada (アナザーフォルム Anazā Forumu). \r\nLa historia involucra un disturbio que sucede en la cima del Monte Corona, que crea un portal al llamado \"Mundo Distorsión (según la versión americana)\" (やぶれたせかい Yabureta Sekai), mundo natal de Giratina, en donde no existe ni el espacio ni el tiempo y en el que se desafían las leyes de la física', '2008-09-13', 'RPG', NULL, 'singleplayer', );
INSERT INTO `juego` (`id`, `id_desarrollador`, `nombre`, `descripcion`, `fecha_lanzamiento`, `genero1`, `genero2`, `tipo`, `imagen`) VALUES
(4, 13, 'RAID: Shadow Legends', 'Juego de rol por turnos con elementos de gacha, ambientado en un mundo de fantasía oscura.', '2018-07-04', 'RPG', 'Gacha', 'single/multiplayer', );
INSERT INTO `juego` (`id`, `id_desarrollador`, `nombre`, `descripcion`, `fecha_lanzamiento`, `genero1`, `genero2`, `tipo`, `imagen`) VALUES
(5, 14, 'Puzzle Forge Dungeon', 'Combina la forja de armas con mecánicas de puzles en un dungeon crawler estratégico.', '2021-09-07', 'Puzzle', 'Estrategia', 'singleplayer', );
INSERT INTO `juego` (`id`, `id_desarrollador`, `nombre`, `descripcion`, `fecha_lanzamiento`, `genero1`, `genero2`, `tipo`, `imagen`) VALUES
(6, 11, 'River King: Mystic Valley', 'Aventura de pesca con elementos de rol, donde buscas al legendario Rey del Río.', '2008-04-29', 'Aventura', 'Deportes', 'singleplayer', );
INSERT INTO `juego` (`id`, `id_desarrollador`, `nombre`, `descripcion`, `fecha_lanzamiento`, `genero1`, `genero2`, `tipo`, `imagen`) VALUES
(7, 16, 'Mystic Valley Battleground', 'Juego de rol y estrategia donde exploras valles místicos y enfrentas monstruos.', '2023-10-30', 'RPG', 'Estrategia', 'singleplayer', );
INSERT INTO `juego` (`id`, `id_desarrollador`, `nombre`, `descripcion`, `fecha_lanzamiento`, `genero1`, `genero2`, `tipo`, `imagen`) VALUES
(8, 17, 'Speedrush', 'Juego de carreras futuristas con vehículos de alta velocidad en circuitos urbanos.', '2023-11-15', 'Carreras', 'Futurista', 'single/multiplayer', );
INSERT INTO `juego` (`id`, `id_desarrollador`, `nombre`, `descripcion`, `fecha_lanzamiento`, `genero1`, `genero2`, `tipo`, `imagen`) VALUES
(9, 11, 'The Legend of Zelda: Breath of the Wild', 'Aventura en mundo abierto donde Link despierta para salvar Hyrule.', '2017-03-03', 'Aventura', 'Acción', 'singleplayer', );
INSERT INTO `juego` (`id`, `id_desarrollador`, `nombre`, `descripcion`, `fecha_lanzamiento`, `genero1`, `genero2`, `tipo`, `imagen`) VALUES
(10, 18, 'Dark Souls III', 'Juego de rol y acción con un desafiante sistema de combate y una ambientación oscura.', '2016-04-12', 'RPG', 'Acción', 'single/multiplayer', );
INSERT INTO `juego` (`id`, `id_desarrollador`, `nombre`, `descripcion`, `fecha_lanzamiento`, `genero1`, `genero2`, `tipo`, `imagen`) VALUES
(11, 19, 'Overwatch 2', 'Shooter en equipo con héroes únicos y múltiples modos de juego online.', '2022-10-04', 'FPS', 'Shooter', 'multiplayer', );
INSERT INTO `juego` (`id`, `id_desarrollador`, `nombre`, `descripcion`, `fecha_lanzamiento`, `genero1`, `genero2`, `tipo`, `imagen`) VALUES
(12, 24, 'Hollow Knight', 'Metroidvania de acción y exploración en un mundo subterráneo lleno de misterios.', '2017-02-24', 'Metroidvania', 'Plataformas', 'singleplayer', );
INSERT INTO `juego` (`id`, `id_desarrollador`, `nombre`, `descripcion`, `fecha_lanzamiento`, `genero1`, `genero2`, `tipo`, `imagen`) VALUES
(13, 20, 'Cyberpunk 2077', 'RPG de mundo abierto ambientado en un futuro distópico con temática cyberpunk.', '2020-12-10', 'RPG', 'Mundo Abierto', 'singleplayer', );
INSERT INTO `juego` (`id`, `id_desarrollador`, `nombre`, `descripcion`, `fecha_lanzamiento`, `genero1`, `genero2`, `tipo`, `imagen`) VALUES
(14, 20, 'The Witcher 3: Wild Hunt', 'Épica aventura de rol en mundo abierto siguiendo las historias del brujo Geralt de Rivia.', '2015-05-19', 'RPG', 'Aventura', 'singleplayer', );
INSERT INTO `juego` (`id`, `id_desarrollador`, `nombre`, `descripcion`, `fecha_lanzamiento`, `genero1`, `genero2`, `tipo`, `imagen`) VALUES
(15, 21, 'Valorant', 'FPS táctico por equipos con habilidades únicas y enfoque competitivo.', '2020-06-02', 'Shooter', 'Táctico', 'multiplayer', );
INSERT INTO `juego` (`id`, `id_desarrollador`, `nombre`, `descripcion`, `fecha_lanzamiento`, `genero1`, `genero2`, `tipo`, `imagen`) VALUES
(16, 22, 'Minecraft', 'Sandbox creativo de construcción y supervivencia en un mundo generado por bloques.', '2011-11-18', 'Sandbox', 'Supervivencia', 'single/multiplayer', );
INSERT INTO `juego` (`id`, `id_desarrollador`, `nombre`, `descripcion`, `fecha_lanzamiento`, `genero1`, `genero2`, `tipo`, `imagen`) VALUES
(17, 23, 'Overcooked! 2', 'Caótico juego cooperativo de cocina donde trabajas en equipo para preparar platos.', '2018-08-07', 'Simulación', 'Party', 'single/multiplayer', );
INSERT INTO `juego` (`id`, `id_desarrollador`, `nombre`, `descripcion`, `fecha_lanzamiento`, `genero1`, `genero2`, `tipo`, `imagen`) VALUES
(24, 19, 'sjfls', 'skjdfslfj', '2025-05-21', 'afalfj', 'askfj', 'singleplayer', );
INSERT INTO `juego` (`id`, `id_desarrollador`, `nombre`, `descripcion`, `fecha_lanzamiento`, `genero1`, `genero2`, `tipo`, `imagen`) VALUES
(25, 19, 'Diablo IV', 'En este juego, los jugadores exploran el mundo abierto de Santuario, un lugar devastado por conflictos pasados, lleno de demonios, monstruos y cultos oscuros. A diferencia de entregas anteriores, Diablo IV presenta un mundo interconectado y continuo, donde puedes viajar libremente entre regiones, ya sea solo o acompañado.\n\nEl juego ofrece varias clases jugables, cada una con habilidades únicas y árboles de personalización. A medida que avanzas, tu personaje mejora, obtienes equipo más poderoso y desbloqueas nuevas formas de jugar.', '2025-06-11', 'Aventura', 'RPG', 'single/multiplayer', );
INSERT INTO `juego` (`id`, `id_desarrollador`, `nombre`, `descripcion`, `fecha_lanzamiento`, `genero1`, `genero2`, `tipo`, `imagen`) VALUES
(26, 21, 'legend of legends', 'Es un juego de estrategia en línea donde dos equipos de cinco jugadores compiten entre sí para destruir la base del equipo contrario. Cada jugador controla un “campeón” con habilidades únicas y debe colaborar con su equipo, derrotar enemigos, tomar objetivos en el mapa y avanzar hasta derribar el nexo enemigo (la estructura principal). El mapa principal se llama la Grieta del Invocador, y el juego combina acción, táctica y trabajo en equipo.', '2025-06-16', 'MOBA', 'Acción', 'single/multiplayer', ),
(27, 18, 'Elden Ring', 'El juego se desarrolla en las Tierras Intermedias (The Lands Between), un mundo abierto masivo, oscuro, misterioso y bellamente diseñado, lleno de castillos, ruinas, bosques, pantanos y montañas. No tienes un marcador que te lo explique todo: debes explorar, descubrir caminos ocultos y encontrar tu propio rumbo.', '2025-06-20', 'RPG', 'Aventura', 'single/multiplayer', ),
(28, 18, 'Dark Souls II', 'El juego te lleva al reino de Drangleic, un lugar arruinado y decadente lleno de castillos derrumbados, cuevas sombrías, bosques malditos y fortalezas olvidadas. El mundo está interconectado (aunque menos cohesivo que en Dark Souls I), y tú, como un no-muerto marcado por la maldición, exploras buscando respuestas y poder para romper tu destino.', '2025-06-12', 'RPG', 'Accion', 'singleplayer', );

